import{_ as s,a as o,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 全册短语与句型 · 第49–74课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第二册：实践与进步 · 全册短语与句型 · 第49–74课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-2/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-2/phrases-part-02"},"next":{"text":"第二册：实践与进步 · 全册短语与句型 · 第75–96课","link":"/life/english/new-concept/book-2/phrases-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册短语与句型 · 第24–48课","link":"/life/english/new-concept/book-2/phrases-part-02"},"next":{"text":"第二册：实践与进步 · 全册短语与句型 · 第75–96课","link":"/life/english/new-concept/book-2/phrases-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-2/phrases-part-03.md","filePath":"life/english/new-concept/book-2/phrases-part-03.md"}'),l={name:"life/english/new-concept/book-2/phrases-part-03.md"};function i(t,e,r,h,p,d){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第二册-实践与进步-·-全册短语与句型-·-第49–74课" tabindex="-1">第二册：实践与进步 · 全册短语与句型 · 第49–74课 <a class="header-anchor" href="#第二册-实践与进步-·-全册短语与句型-·-第49–74课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册短语与句型 · 第49–74课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="lesson-49-·-叙事中的时态与衔接" tabindex="-1">Lesson 49 · 叙事中的时态与衔接 <a class="header-anchor" href="#lesson-49-·-叙事中的时态与衔接" aria-label="Permalink to &quot;Lesson 49 · 叙事中的时态与衔接 {#lesson-49-·-叙事中的时态与衔接}&quot;">​</a></h2><ul><li>blow away — 吹走，代词放中间</li><li>wake somebody up — 把某人叫醒</li></ul><p><strong>句型示范：</strong> I was sleeping on the terrace when a gust blew my blanket away.</p><p>was sleeping 是背景，when 引出 blew；blow 的过去式为 blew，away 表离开原处。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-049">进入本课</a></p><h2 id="lesson-50-·-过去完成时与先后关系" tabindex="-1">Lesson 50 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-50-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 50 · 过去完成时与先后关系 {#lesson-50-·-过去完成时与先后关系}&quot;">​</a></h2><ul><li>get off — 下车，不用于上飞机</li><li>on the way to — 在去……的路上</li></ul><p><strong>句型示范：</strong> By the time I asked, the bus had passed my stop.</p><p>By the time 从句 asked 定位过去时刻，had passed 说明更早已发生的事件；my stop 是目的站。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-050">进入本课</a></p><h2 id="lesson-51-·-完成进行时与持续活动" tabindex="-1">Lesson 51 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-51-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 51 · 完成进行时与持续活动 {#lesson-51-·-完成进行时与持续活动}&quot;">​</a></h2><ul><li>give up doing — 放弃做某事</li><li>for two weeks — 持续两周，不是两周前</li></ul><p><strong>句型示范：</strong> Tess has been avoiding sweet snacks for two weeks.</p><p>has been avoiding 是完成进行时，for two weeks 是持续长度，sweet snacks 是宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-051">进入本课</a></p><h2 id="lesson-52-·-现在完成时与过去时间" tabindex="-1">Lesson 52 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-52-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 52 · 现在完成时与过去时间 {#lesson-52-·-现在完成时与过去时间}&quot;">​</a></h2><ul><li>be covered with — 覆盖着某物，强调状态</li><li>clear away — 清除，代词用 clear it away</li></ul><p><strong>句型示范：</strong> Fallen leaves have covered the path outside our classroom.</p><p>Fallen leaves 是复数主语，have covered 为完成时；outside our classroom 修饰 path。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-052">进入本课</a></p><h2 id="lesson-53-·-被动语态与信息重点" tabindex="-1">Lesson 53 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-53-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 53 · 被动语态与信息重点 {#lesson-53-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>cut off the power — 切断电源</li><li>find the cause of — 找出……的原因</li></ul><p><strong>句型示范：</strong> The power failure was caused by a damaged wire.</p><p>failure 为单数主语，was caused 是过去被动，by 引出原因；damaged 是过去分词作定语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-053">进入本课</a></p><h2 id="lesson-54-·-时间、原因与让步从句" tabindex="-1">Lesson 54 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-54-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 54 · 时间、原因与让步从句 {#lesson-54-·-时间、原因与让步从句}&quot;">​</a></h2><ul><li>wipe something off — 擦去某物</li><li>be covered in — 沾满、覆盖着某物</li></ul><p><strong>句型示范：</strong> As soon as I opened the jar, jam ran over my fingers.</p><p>As soon as 引出开罐动作，ran 为 run 的过去式；over my fingers 描述流过的表面。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-054">进入本课</a></p><h2 id="lesson-55-·-一般过去时与事件顺序" tabindex="-1">Lesson 55 · 一般过去时与事件顺序 <a class="header-anchor" href="#lesson-55-·-一般过去时与事件顺序" aria-label="Permalink to &quot;Lesson 55 · 一般过去时与事件顺序 {#lesson-55-·-一般过去时与事件顺序}&quot;">​</a></h2><ul><li>dig for — 挖掘寻找某物</li><li>turn out to be — 结果证明是，与原先预期可能不同</li></ul><p><strong>句型示范：</strong> People once believed that the field contained gold.</p><p>believed 是主句过去式，that 从句 contained 是当时的信念内容，不代表作者认可它为事实。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-055">进入本课</a></p><h2 id="lesson-56-·-比较级与比较范围" tabindex="-1">Lesson 56 · 比较级与比较范围 <a class="header-anchor" href="#lesson-56-·-比较级与比较范围" aria-label="Permalink to &quot;Lesson 56 · 比较级与比较范围 {#lesson-56-·-比较级与比较范围}&quot;">​</a></h2><ul><li>at a speed of — 以……的速度，后接数值单位</li><li>break a record — 打破纪录</li></ul><p><strong>句型示范：</strong> The new car was much faster than the team&#39;s previous model.</p><p>much 修饰比较级 faster，than 后明确比较对象；previous model 与 new car 都指车型。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-056">进入本课</a></p><h2 id="lesson-57-·-情态动词的意义与形式" tabindex="-1">Lesson 57 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-57-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 57 · 情态动词的意义与形式 {#lesson-57-·-情态动词的意义与形式}&quot;">​</a></h2><ul><li>look down on — 轻视某人</li><li>treat somebody with respect — 尊重地对待某人</li></ul><p><strong>句型示范：</strong> Would you like to see a different size?</p><p>Would you like 后接 to see，a different size 是宾语；would 在此不表过去时间。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-057">进入本课</a></p><h2 id="lesson-58-·-时间、原因与让步从句" tabindex="-1">Lesson 58 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-58-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 58 · 时间、原因与让步从句 {#lesson-58-·-时间、原因与让步从句}&quot;">​</a></h2><ul><li>lead to — 导致，to 是介词</li><li>in the long run — 从长远来看</li></ul><p><strong>句型示范：</strong> Although the flood damaged the garden, it led to better drainage.</p><p>Although 从句承认不利事实，主句 led to 引出后续结果；it 指 flood。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-058">进入本课</a></p><h2 id="lesson-59-·-动词、宾语与补足语" tabindex="-1">Lesson 59 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-59-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 59 · 动词、宾语与补足语 {#lesson-59-·-动词、宾语与补足语}&quot;">​</a></h2><ul><li>let somebody in — 让某人进来</li><li>without doing — 不做某事的情况下</li></ul><p><strong>句型示范：</strong> The new flap lets the cat enter without waking us.</p><p>lets 为单数谓语，the cat 是宾语，enter 是原形补足语；without waking 为介词加动名词。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-059">进入本课</a></p><h2 id="lesson-60-·-将来表达与安排" tabindex="-1">Lesson 60 · 将来表达与安排 <a class="header-anchor" href="#lesson-60-·-将来表达与安排" aria-label="Permalink to &quot;Lesson 60 · 将来表达与安排 {#lesson-60-·-将来表达与安排}&quot;">​</a></h2><ul><li>by evening — 到傍晚之前或时，不等于整个傍晚</li><li>make a prediction — 作出预测</li></ul><p><strong>句型示范：</strong> The guide predicted that we would see clear skies by evening.</p><p>predicted 为过去报告动词，would see 是从过去视角看将来，by evening 给出截止时间。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-060">进入本课</a></p><h2 id="lesson-61-·-被动语态与信息重点" tabindex="-1">Lesson 61 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-61-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 61 · 被动语态与信息重点 {#lesson-61-·-被动语态与信息重点}&quot;">​</a></h2><ul><li>put something right — 纠正、修好某事</li><li>by the end of — 到……结束之前或时</li></ul><p><strong>句型示范：</strong> By Friday, the replacement camera will have been tested twice.</p><p>will have been tested 为将来完成时被动，By Friday 给出截止点，twice 是次数。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-061">进入本课</a></p><h2 id="lesson-62-·-完成进行时与持续活动" tabindex="-1">Lesson 62 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-62-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 62 · 完成进行时与持续活动 {#lesson-62-·-完成进行时与持续活动}&quot;">​</a></h2><ul><li>put out a fire — 扑灭火</li><li>take root — 生根，也可比喻建立起来</li></ul><p><strong>句型示范：</strong> The volunteers had been planting seeds for hours when the rain began.</p><p>had been planting 强调雨开始前持续的活动，when rain began 提供过去参照点。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-062">进入本课</a></p><h2 id="lesson-63-·-间接引语与视角转换" tabindex="-1">Lesson 63 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-63-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 63 · 间接引语与视角转换 {#lesson-63-·-间接引语与视角转换}&quot;">​</a></h2><ul><li>tell a joke — 讲笑话，不用 say a joke</li><li>make somebody laugh — 逗某人笑，laugh 前不加 to</li></ul><p><strong>句型示范：</strong> The host asked me not to repeat the joke.</p><p>asked 后接 me，再用 not to repeat 转述否定请求；the joke 是 repeat 的宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-063">进入本课</a></p><h2 id="lesson-64-·-非真实条件句" tabindex="-1">Lesson 64 · 非真实条件句 <a class="header-anchor" href="#lesson-64-·-非真实条件句" aria-label="Permalink to &quot;Lesson 64 · 非真实条件句 {#lesson-64-·-非真实条件句}&quot;">​</a></h2><ul><li>link A with B — 连接两处</li><li>go ahead with — 继续实施某计划</li></ul><p><strong>句型示范：</strong> If the earlier plan had succeeded, the route would have opened sooner.</p><p>had succeeded 是过去反事实条件，would have opened 是未发生的假设结果，sooner 比较时间早晚。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-064">进入本课</a></p><h2 id="lesson-65-·-动词、宾语与补足语" tabindex="-1">Lesson 65 · 动词、宾语与补足语 <a class="header-anchor" href="#lesson-65-·-动词、宾语与补足语" aria-label="Permalink to &quot;Lesson 65 · 动词、宾语与补足语 {#lesson-65-·-动词、宾语与补足语}&quot;">​</a></h2><ul><li>get out of the way — 让开道路</li><li>lead somebody away — 把某人带离</li></ul><p><strong>句型示范：</strong> The keeper made the elephant move towards a basket of fruit.</p><p>made 后接宾语 elephant，再用原形 move 作补足语；towards 只说明方向。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-065">进入本课</a></p><h2 id="lesson-66-·-完成进行时与持续活动" tabindex="-1">Lesson 66 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-66-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 66 · 完成进行时与持续活动 {#lesson-66-·-完成进行时与持续活动}&quot;">​</a></h2><ul><li>smell of — 带有……的气味</li><li>check for — 检查是否存在某问题</li></ul><p><strong>句型示范：</strong> A jar of honey has been leaking inside the delivery van.</p><p>A jar 为单数主语，has been leaking 表持续过程；of honey 说明内容物，inside 为地点。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-066">进入本课</a></p><h2 id="lesson-67-·-完成进行时与持续活动" tabindex="-1">Lesson 67 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-67-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 67 · 完成进行时与持续活动 {#lesson-67-·-完成进行时与持续活动}&quot;">​</a></h2><ul><li>keep a record of — 记录某事</li><li>show signs of — 显示出……的迹象</li></ul><p><strong>句型示范：</strong> The scientists have been monitoring the volcano since March.</p><p>have been monitoring 是完成进行时，since March 给起点；scientists 是复数主语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-067">进入本课</a></p><h2 id="lesson-68-·-动名词与动词搭配" tabindex="-1">Lesson 68 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-68-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 68 · 动名词与动词搭配 {#lesson-68-·-动名词与动词搭配}&quot;">​</a></h2><ul><li>insist on doing — 坚持做某事</li><li>avoid doing — 避免做某事，avoid 后不加 to</li></ul><p><strong>句型示范：</strong> My neighbour insisted on helping me carry the boxes.</p><p>insisted on 是谓语搭配，helping 为介词宾语；help me carry 中 carry 可不带 to。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-068">进入本课</a></p><h2 id="lesson-69-·-不定式与目的" tabindex="-1">Lesson 69 · 不定式与目的 <a class="header-anchor" href="#lesson-69-·-不定式与目的" aria-label="Permalink to &quot;Lesson 69 · 不定式与目的 {#lesson-69-·-不定式与目的}&quot;">​</a></h2><ul><li>apply the brakes — 踩刹车、制动</li><li>by mistake — 由于弄错，不是有意行为</li></ul><p><strong>句型示范：</strong> The learner was told to stop beside the yellow line.</p><p>was told 是被动转述，to stop 是要求内容，beside the yellow line 为位置。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-069">进入本课</a></p><h2 id="lesson-70-·-分词修饰与逻辑主语" tabindex="-1">Lesson 70 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-70-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 70 · 分词修饰与逻辑主语 {#lesson-70-·-分词修饰与逻辑主语}&quot;">​</a></h2><ul><li>draw attention to — 使人注意某事</li><li>keep away from — 远离某物</li></ul><p><strong>句型示范：</strong> Waving a red flag, the steward guided the visitors away.</p><p>Waving 的执行者是 the steward；guided 是主句过去式，the visitors 是宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-070">进入本课</a></p><h2 id="lesson-71-·-非真实条件句" tabindex="-1">Lesson 71 · 非真实条件句 <a class="header-anchor" href="#lesson-71-·-非真实条件句" aria-label="Permalink to &quot;Lesson 71 · 非真实条件句 {#lesson-71-·-非真实条件句}&quot;">​</a></h2><ul><li>strike the hour — 整点报时</li><li>keep time — 走时准确、计时</li></ul><p><strong>句型示范：</strong> If the clock had not been repaired, it would have stopped that winter.</p><p>if 从句 had not been repaired 为过去完成被动；主句 would have stopped 表未发生的过去结果。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-071">进入本课</a></p><h2 id="lesson-72-·-分词修饰与逻辑主语" tabindex="-1">Lesson 72 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-72-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 72 · 分词修饰与逻辑主语 {#lesson-72-·-分词修饰与逻辑主语}&quot;">​</a></h2><ul><li>make an attempt — 作一次尝试</li><li>on average — 平均而言，后文需说明统计范围</li></ul><p><strong>句型示范：</strong> A car called Silver Finch completed three test runs.</p><p>called Silver Finch 修饰 A car，completed 才是主句谓语，three test runs 为宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-072">进入本课</a></p><h2 id="lesson-73-·-现在完成时与过去时间" tabindex="-1">Lesson 73 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-73-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 73 · 现在完成时与过去时间 {#lesson-73-·-现在完成时与过去时间}&quot;">​</a></h2><ul><li>hold a record — 保持一项纪录</li><li>so many times — 如此多次，times 表次数可数</li></ul><p><strong>句型示范：</strong> Ella has crossed the border with her family five times this year.</p><p>has crossed 是完成时，five times 为次数，with her family 明确同行者，this year 的范围包含现在。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-073">进入本课</a></p><h2 id="lesson-74-·-定语从句与指代" tabindex="-1">Lesson 74 · 定语从句与指代 <a class="header-anchor" href="#lesson-74-·-定语从句与指代" aria-label="Permalink to &quot;Lesson 74 · 定语从句与指代 {#lesson-74-·-定语从句与指代}&quot;">​</a></h2><ul><li>keep a secret — 保守秘密</li><li>leave somebody alone — 不打扰某人</li></ul><p><strong>句型示范：</strong> The visitor who recognised the actor kept her secret.</p><p>who 指 the visitor 并作 recognised 的主语；kept 是主句谓语，her 指前文 actor。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-074">进入本课</a></p>',133)])])}const g=s(l,[["render",i]]);export{u as __pageData,g as default};
